"""Generate firmware constants with valid C literals and explicit protection semantics."""
from pathlib import Path


def cf(value):
    s = format(float(value), '.12g')
    if '.' not in s and 'e' not in s.lower():
        s += '.0'
    return '(' + s + 'f)'


def write_header(path, calc, loop, ch):
    s, p = calc['sensing'], calc['protection']
    full = 2 ** s['adc_bits'] - 1
    out = [
        '/* Generated by export_handoff.py / handoff_header.py; do not edit. */',
        f'/* revision {ch["revision"]}; conditional_review; implementation closures in design_spec.json. */',
        '#ifndef BOOST_PARAMS_H', '#define BOOST_PARAMS_H', '',
        '/* Constants only: no verified MCU/ADC/COMP/DAC/break routing or enable sequence. */',
        '#define BOOST_DESIGN_CONDITIONAL_REVIEW 1u',
    ]
    def define(name, value, integer=False):
        if integer:
            assert int(value) == value
        out.append(f'#define {name:<30} {str(int(value)) + "u" if integer else cf(value)}')
    out += ['', '/* Edge-aligned PWM; RCR is not a divider for every ADC compare trigger. */']
    for k, v in [('PWM_FSW_HZ', calc['inputs']['fsw_hz']), ('PWM_TIM_CLK_HZ', calc['pwm']['timer_clk_hz']),
                 ('PWM_ARR', calc['pwm']['arr']), ('PWM_CCR_MAX', p['duty_limit']['ccr_max']),
                 ('CTRL_FREQ_HZ', calc['timing']['f_ctrl_hz']), ('TIM1_RCR', calc['timing']['tim1_rcr'])]:
        define(k, v, True)
    define('CTRL_TS_S', 1 / calc['timing']['f_ctrl_hz'])
    out += ['', '/* Nominal ADC scaling: physical value = code * K; apply measured calibration. */']
    define('ADC_FULL_SCALE', full, True)
    define('ADC_VREF_V', s['adc_vref_v'])
    define('VOUT_V_PER_CODE', s['adc_vref_v'] / full / s['vout']['ratio'])
    define('IOUT_A_PER_CODE', s['adc_vref_v'] / full / s['iout']['transimpedance_v_per_a'])
    define('VIN_V_PER_CODE', s['adc_vref_v'] / full / s['vin']['ratio'])
    define('IOUT_SHUNT_OHM', s['iout']['shunt_ohm'])
    define('IOUT_CSA_GAIN', s['iout']['gain'])
    define('IOUT_FILTER_R_OHM', ch['losses']['current_filter_r_ohm'])
    define('IOUT_FILTER_C_F', ch['losses']['current_filter_c_f'])
    out += ['', '/* Setpoints and conservative CC planning range; lower values are uncontrolled. */']
    define('VOUT_SET_V', calc['inputs']['vout_v'])
    define('IOUT_SET_A', calc['inputs']['iout_cc_a'])
    define('CC_VOUT_MIN_V', calc['cc_range']['vo_min_v'])
    define('CC_VOUT_MAX_V', calc['inputs']['vout_v'])
    define('CC_CR_MIN_OHM', calc['cc_range']['r_min_ohm'])
    define('CC_CR_MAX_OHM', calc['cc_range']['r_max_ohm'])
    define('SOFTSTART_MS', p['soft_start']['ramp_ms'], True)
    out += ['', '/* PI initial values: e in V/A, u in duty 0..1; one control-step integral update. */',
            '/* Inactive integral state = actual_duty - Kp*e; active loop needs anti-windup. */',
            '/* Includes modeled analog filtering, one-step delay and ZOH; changes require re-analysis. */']
    for mode in ('CV', 'CC'):
        define(mode + '_KP', loop[mode]['Kp'])
        define(mode + '_KI_TS', loop[mode]['Ki_Tc'])
    define('DUTY_MIN', p['duty_limit']['dmin'])
    define('DUTY_MAX', p['duty_limit']['dmax'])
    out += ['', '/* Nominal thresholds; hardware ADC-equivalent codes ARE NOT verified DAC codes. */',
            '/* B/D must determine independent DAC channels, scaling, tolerance and COMP/break routing. */']
    for key, field in [('OVP_SW_V', 'ovp_sw'), ('OVP_HW_V', 'ovp_hw'),
                       ('OCP_SW_A', 'ocp_sw'), ('OCP_HW_A', 'ocp_hw')]:
        define(key, p[field]['value'])
        define(key.rsplit('_', 1)[0] + '_ADC_EQ_CODE', p[field]['adc_code'], True)
    define('OCP_SW_DELAY_MS', p['ocp_sw']['delay_ms'], True)
    define('UVLO_OFF_V', p['uvlo']['off_v'])
    define('UVLO_ON_V', p['uvlo']['on_v'])
    out += ['', '/* Hardware break must latch PWM OFF; disable automatic output re-enable.',
            ' * Fault/UVLO recovery requires explicit reset, self-check and a new start.',
            ' * Output OCP is NOT cycle-by-cycle inductor current limiting.',
            ' * PWM OFF does not isolate output. Independent input fault protection is required.',
            ' * Digital reference ramp does not limit insertion pass-through inrush.',
            ' * ADC invalid/stale/saturated data must not continue closed-loop operation.',
            ' * CALIB loads checked data; zero current only when real current is verified absent.',
            ' */', '', '#endif /* BOOST_PARAMS_H */', '']
    Path(path).write_text('\n'.join(out), encoding='utf-8')
